builder.Host.ConfigureAppConfiguration((context, config) =>
{
    var built = config.Build();
    config.AddAzureKeyVault(
        new Uri(built["KeyVaultUrl"]),
        new DefaultAzureCredential(),
        new AzureKeyVaultConfigurationOptions
        {
            // Reload when Key Vault sends a change notification
            ReloadAfter = TimeSpan.FromSeconds(5)
        });
});

// React app (no secrets here):
async function fetchWeather() {
  const response = await fetch('/api/weather');
  const data = await response.json();
  return data;
}

// .NET backend (holds the secret):
app.MapGet("/api/weather", async (IConfiguration config) =>
{
    var apiKey = config["WeatherApi:Key"]; // from Key Vault
    var response = await httpClient.GetAsync(
        $"https://api.weather.com/current?key={apiKey}&q=London");
    return Results.StreamContent(await response.Content.ReadAsStreamAsync());
});
